const thresholdInsideRectangle = RECTANGLE_THRESHOLD_STRATEGY.strategyFunction;
export { RECTANGLE_STRATEGY, RECTANGLE_THRESHOLD_STRATEGY, fillInsideRectangle, thresholdInsideRectangle, };
